<template><article class="card"><router-link :to="`/products/${product.slug}`" class="product-link"><div class="image"><img v-if="image" :src="image" :alt="title" loading="lazy"/><span class="condition">{{ condition }}</span><span v-if="discount" class="discount">-{{ discount }}%</span></div><div class="copy"><p>{{ product.brand || 'CURATED FIND' }}</p><h3>{{ title }}</h3><div class="price"><strong>€{{ money(product.sale_price) }}</strong><del v-if="product.original_price">€{{ money(product.original_price) }}</del></div><small>{{ stockCopy }}</small></div></router-link><div class="card-actions"><button class="save" :aria-label="saved?'Remove from saved products':'Save product'" @click="toggleSave">{{ saved?'♥':'♡' }}</button><button class="add" :disabled="unavailable||adding" @click="add">{{ unavailable?'Unavailable':adding?'Adding…':'Add to cart' }}</button></div><p v-if="message" class="feedback" role="status">{{ message }}</p></article></template>
<script setup>
import { computed, ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import { saveProduct,unsaveProduct } from '../api';import { useAuth } from '../composables/useAuth';import { useCart } from '../composables/useCart'
const props=defineProps({product:{type:Object,required:true},initiallySaved:{type:Boolean,default:false}}),router=useRouter(),route=useRoute(),{isAuthenticated}=useAuth(),{addToCart}=useCart();const saved=ref(props.initiallySaved),adding=ref(false),message=ref('')
const title=computed(()=>props.product.title_en||props.product.title||'Product'),image=computed(()=>props.product.images?.[0]?.thumbnail_url||props.product.images?.[0]?.image_url||props.product.image_url),condition=computed(()=>({new:'New',like_new:'Like new',good:'Good',fair:'Fair',poor:'Well loved',for_parts:'For parts'}[props.product.condition_grade]||'Pre-loved')),unavailable=computed(()=>props.product.status!=='active'||Number(props.product.stock_quantity)===0),discount=computed(()=>{const a=Number(props.product.sale_price),b=Number(props.product.original_price);return b>a?Math.round((1-a/b)*100):0}),stockCopy=computed(()=>unavailable.value?'Currently unavailable':Number(props.product.stock_quantity)>0?`${props.product.stock_quantity} available`:'Ready to ship')
const money=v=>Number(v||0).toFixed(2)
async function add(){adding.value=true;message.value='';try{await addToCart(props.product);message.value='Added to cart'}catch(e){message.value=e.message||'Could not add this item'}finally{adding.value=false;setTimeout(()=>message.value='',1800)}}
async function toggleSave(){if(!isAuthenticated.value){router.push({path:'/login',query:{redirect:route.fullPath}});return}try{saved.value?await unsaveProduct(props.product.id):await saveProduct(props.product.id);saved.value=!saved.value}catch{message.value='Could not update saved products'}}
</script>
<style scoped>.card{position:relative;overflow:hidden;border:1px solid rgba(23,63,52,.09);border-radius:22px;background:#fffdf8;box-shadow:0 9px 28px rgba(23,63,52,.06);transition:.2s}.card:hover{transform:translateY(-3px);box-shadow:0 15px 38px rgba(23,63,52,.11)}.product-link{display:block;color:#173f34}.image{position:relative;aspect-ratio:1/1;background:#e5e7e2;overflow:hidden}.image img{width:100%;height:100%;object-fit:cover;transition:.35s}.card:hover .image img{transform:scale(1.035)}.condition,.discount{position:absolute;top:12px;padding:6px 9px;border-radius:999px;background:rgba(255,253,248,.94);font-size:9px;font-weight:900;text-transform:uppercase;letter-spacing:.09em}.condition{left:12px}.discount{right:12px;background:#dff263}.copy{padding:15px 15px 12px}.copy>p{margin:0 0 5px;color:#7a8680;font-size:9px;font-weight:900;letter-spacing:.14em}.copy h3{min-height:42px;margin:0;font:700 17px/1.25 Georgia,serif}.price{display:flex;align-items:baseline;gap:8px;margin-top:12px}.price strong{font:700 22px Georgia,serif}.price del{color:#909894;font-size:11px}.copy small{display:block;margin-top:7px;color:#7a8680;font-size:10px}.card-actions{display:grid;grid-template-columns:43px 1fr;gap:7px;padding:0 12px 13px}.card-actions button{height:42px;border-radius:999px;font-weight:850}.save{border:1px solid #ced5cf;background:white;color:#173f34;font-size:19px}.add{border:0;background:#173f34;color:white;font-size:11px}.add:disabled{background:#9aa59f}.feedback{position:absolute;right:10px;bottom:60px;left:10px;margin:0;padding:7px;border-radius:9px;background:#dff263;text-align:center;font-size:10px;font-weight:800}</style>
